ALTER TABLE person ADD COLUMN IF NOT EXISTS public_id uuid;
ALTER TABLE person ADD COLUMN IF NOT EXISTS email text;
ALTER TABLE person ADD COLUMN IF NOT EXISTS email_normalized text;
ALTER TABLE person ADD COLUMN IF NOT EXISTS state text NOT NULL DEFAULT 'active';
ALTER TABLE person ADD COLUMN IF NOT EXISTS version bigint NOT NULL DEFAULT 1;
ALTER TABLE person ADD COLUMN IF NOT EXISTS updated_at timestamptz;
ALTER TABLE person ADD COLUMN IF NOT EXISTS updated_by uuid;
UPDATE person SET public_id=gen_random_uuid() WHERE public_id IS NULL;
ALTER TABLE person ALTER COLUMN public_id SET DEFAULT gen_random_uuid();
ALTER TABLE person ALTER COLUMN public_id SET NOT NULL;
ALTER TABLE person DROP CONSTRAINT IF EXISTS person_state_check;
ALTER TABLE person ADD CONSTRAINT person_state_check CHECK(state IN('active','ended'));
CREATE UNIQUE INDEX IF NOT EXISTS person_public_id_unique ON person(public_id);
DROP INDEX IF EXISTS person_email_candidate_idx;
CREATE UNIQUE INDEX IF NOT EXISTS person_email_normalized_unique ON person(email_normalized) WHERE email_normalized IS NOT NULL;
CREATE TABLE IF NOT EXISTS unit (id uuid PRIMARY KEY,public_id uuid NOT NULL UNIQUE,identifier text NOT NULL,identifier_normalized text NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','ended')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL,created_by uuid NOT NULL,updated_at timestamptz,updated_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS unit_identifier_normalized_unique ON unit(identifier_normalized);
CREATE TABLE IF NOT EXISTS person_unit_relationship (id uuid PRIMARY KEY,public_id uuid NOT NULL UNIQUE,person_id uuid NOT NULL REFERENCES person(id),unit_id uuid NOT NULL REFERENCES unit(id),relation_kind text NOT NULL,starts_on date NOT NULL,ends_on date,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','ended')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL,created_by uuid NOT NULL,updated_at timestamptz,updated_by uuid,CHECK(ends_on IS NULL OR ends_on>starts_on));
CREATE INDEX IF NOT EXISTS relationship_person_idx ON person_unit_relationship(person_id,starts_on,id);
CREATE INDEX IF NOT EXISTS relationship_unit_idx ON person_unit_relationship(unit_id,starts_on,id);
CREATE TABLE IF NOT EXISTS institutional_audit_event (id uuid PRIMARY KEY,request_id text NOT NULL,actor_person_id uuid NOT NULL REFERENCES person(id),event_type text NOT NULL,target_kind text NOT NULL,target_id uuid NOT NULL,before_value jsonb,after_value jsonb,reason text,occurred_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS institutional_audit_target_idx ON institutional_audit_event(target_kind,target_id,occurred_at);
CREATE TABLE IF NOT EXISTS institutional_idempotency (account_id uuid NOT NULL,operation text NOT NULL,idempotency_key_hash text NOT NULL,request_hash text NOT NULL,response_status integer,response_body jsonb,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(account_id,operation,idempotency_key_hash));
ALTER TABLE authority_assignment ADD COLUMN IF NOT EXISTS source_relationship_id uuid;
ALTER TABLE authority_assignment DROP CONSTRAINT IF EXISTS authority_assignment_state_check;
ALTER TABLE authority_assignment ADD CONSTRAINT authority_assignment_state_check CHECK(state IN('pending_verification','active','ended'));
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='authority_assignment'::regclass AND conname='authority_assignment_source_relationship_fk') THEN ALTER TABLE authority_assignment ADD CONSTRAINT authority_assignment_source_relationship_fk FOREIGN KEY(source_relationship_id) REFERENCES person_unit_relationship(id); END IF; END $$;
WITH changed AS (UPDATE authority_assignment SET capabilities=array_append(capabilities,'people-units-relationships.manage'),authorization_version=authorization_version+1 WHERE role_kind='syndic' AND state='active' AND NOT('people-units-relationships.manage'=ANY(capabilities)) RETURNING id,authorization_version) UPDATE burgoweb_global.account_tenant_memberships membership SET authorization_version=changed.authorization_version FROM changed WHERE membership.authority_id=changed.id;
INSERT INTO schema_version(version, applied_at) VALUES (4, CURRENT_TIMESTAMP) ON CONFLICT (version) DO NOTHING;
